package com.github.ytlog.mobby.android.localization

/** UI language is independent of Agent protocols and user-authored content. */
enum class AppLanguage(val tag: String, val nativeName: String) {
    CHINESE("zh", "中文"), ENGLISH("en", "English");

    companion object {
        fun fromTag(tag: String?): AppLanguage = values().firstOrNull { it.tag == tag } ?: CHINESE
        @Volatile var current: AppLanguage = CHINESE
    }
}

/** All application-owned copy. Parameters are inserted once, without interpreting their contents. */
open class StringCatalog(private val fixedLanguage: AppLanguage? = null) {
    protected open val language: AppLanguage get() = fixedLanguage ?: AppLanguage.current
    private fun text(chinese: String, english: String, vararg args: Any?): String {
        val template = if (language == AppLanguage.CHINESE) chinese else english
        return PLACEHOLDER.replace(template) { match -> args[match.groupValues[1].toInt()].toString() }
    }

